public:
    int equalDigitFrequency(string s) {
        int n = s.size();
        unordered_set<string_view> seen;
        string_view sv = s;
        for (int i = 0; i < n; i++) {
            int count[10] = {0};
            int distinct = 0, maxF = 0;
            for (int j = i; j < n; j++) {
                int d = s[j] - '0';
                if (count[d] == 0) distinct++;
