class Solution {
    public int equalDigitFrequency(String s) {
        int n = s.length();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int[] count = new int[10];
            int distinct = 0, maxF = 0;
            for (int j = i; j < n; j++) {
                int d = s.charAt(j) - '0';
                if (count[d] == 0) distinct++;
                count[d]++;
                if (count[d] > maxF) maxF = count[d];
                if (distinct * maxF == (j - i + 1)) {
                    seen.add(s.substring(i, j + 1));
                }
            }
        }
        return seen.size();
    }
}

var equalDigitFrequency = function(s) {
    const n = s.length;
    const seen = new Set();
    for (let i = 0; i < n; i++) {
        const count = new Int32Array(10);
        let distinct = 0, maxF = 0;
        for (let j = i; j < n; j++) {
            const d = s.charCodeAt(j) - 48;
            if (count[d] === 0) distinct++;
            count[d]++;
            if (count[d] > maxF) maxF = count[d];
            if (distinct * maxF === (j - i + 1)) {
                seen.add(s.slice(i, j + 1));
            }
        }
    }
